    47	    async issue(req: Request) {
    48	      return { status: 200, body: await getIssue(req.params.key) };
    49	    },
    50	
    51	    async build(req: Request) {
    52	      return { status: 200, body: await getBuild(req.params.id) };
    53	    },
    54	
